import numpy as np
def equation(t, P, params):
    f = params[0] + params[1]*P + params[2]/P + params[3]*np.sqrt(P) + params[4]*np.log(P) + params[5]*P**2 + params[6]/(1+P**2)
    return f + params[7]*t*np.sqrt(P)
